        `,foundIn:"Livre de base"},{name:"Dissimuler un objet",level:0,tradition:ql,type:"Utilitaire",currentUses:0,target:"Un objet de Gabarit 1/2 ou inf\xE9rieur \xE0 port\xE9e courte",duration:"1 min",effect:`
